263	#[cfg(test)]
264	mod snippet_tests {
265	    use super::*;
266	    use crate::types::{CodeBlock, SymbolKind};
267	    use camino::Utf8PathBuf;
268	
269	    /// Where the test blocks start in their file, so a span offset is not mistaken for an offset in the code.
270	    const START: usize = 100;
271	
272	    /// The snippet at the longest length, which is what every row showed before `--snippet-lines` existed; the tests
273	    /// below that call this pin that contract unchanged.
274	    fn snippet(block: &CodeBlock) -> Option<String> {
275	        super::snippet(block, MAX_SNIPPET_LINES)
276	    }
277	
278	    /// The snippet at an explicit length.
279	    fn snippet_of(block: &CodeBlock, lines: usize) -> Option<String> {
280	        super::snippet(block, lines)
281	    }
282	
283	    /// A block whose head is its first line, as for a function whose body opens at the end of that line.
284	    fn block(line_start: usize, code: &str, matched_lines: &[usize]) -> CodeBlock {
285	        let first_line = code.split('\n').next().unwrap_or("");
286	        CodeBlock {
287	            file: Utf8PathBuf::from("src/a.ts"),
288	            line_start,
289	            line_end: line_start + code.split('\n').count() - 1,
290	            node_kind: SymbolKind::Function,
291	            span: START..START + code.len(),
292	            parent_index: None,
293	            code: code.to_owned(),
294	            symbol_signature: Some(first_line.trim_end_matches(['{', ' ']).to_owned()),
295	            signature_span: Some(START..START + first_line.len()),
296	            where_start: None,
297	            name: None,
298	            matched_lines: matched_lines.to_vec(),
299	            parent: None,
300	        }
301	    }
302	
303	    /// `block` with the head set to the text `head`, which `code` must hold.
304	    fn headed(line_start: usize, code: &str, head: &str, matched_lines: &[usize]) -> CodeBlock {
305	        let at = START + code.find(head).expect("the code holds the head");
306	        CodeBlock { signature_span: Some(at..at + head.len()), ..block(line_start, code, matched_lines) }
307	    }
308	
309	    /// `block` with no signature, as for a variable or a type alias.
310	    fn unsigned(line_start: usize, code: &str, matched_lines: &[usize]) -> CodeBlock {
311	        CodeBlock { symbol_signature: None, signature_span: None, ..block(line_start, code, matched_lines) }
312	    }
