816	    /// The help line `scores` produce under `budget`, or `None` when the whole result is shown.
817	    fn help_line(scores: &[f64], budget: &crate::budget::Budget) -> Option<String> {
818	        let ranked = scored_blocks(scores);
819	        let total = ranked.len();
820	        let view = SearchView { max_results: budget.max_results, ..SearchView::default() };
821	        let texts = search_row_texts(&ranked, view.snippet_lines);
822	        let rendered = render_search(&crate::budget::apply_budget(ranked, total, budget, &texts, Vec::new()), &view);
823	        rendered.lines().find_map(|line| {
824	            let text = line.strip_prefix("help[1]: ")?;
825	            Some(text.strip_prefix('"').and_then(|quoted| quoted.strip_suffix('"')).unwrap_or(text).to_owned())
826	        })
827	    }
