1106	/// Converts an error into a [`michi::DomainError`] for agent output.
1107	pub trait ToDomainError {
1108	    /// Returns a short `snake_case` code that is distinct for each error kind.
1109	    fn monokl_code(&self) -> &'static str;
1110	    /// Converts the error, prefixing the message with [`monokl_code`](Self::monokl_code) and carrying its source chain
1111	    /// as causes.
1112	    fn to_domain_error(&self) -> michi::DomainError;
1113	}
