1	//! The `monokl` command line: parses arguments, runs a command and prints agent-facing output.
2	//!
3	//! This is the agent layer. It budgets a core result and renders it with michi; core never prints.
4	
5	use std::ffi::OsString;
6	use std::io::Write;
7	use std::process::ExitCode;
8	use std::sync::Arc;
9	use std::time::Duration;
10	
11	use camino::Utf8PathBuf;
12	use clap::{Args, Parser, Subcommand, ValueEnum};
13	
14	use crate::analysis::lang::{Language, TEST_DIRS};
15	use crate::analysis::registry::AnalyzerRegistry;
16	use crate::budget::{Budget, apply_budget};
17	use crate::error::MonoklError;
18	use crate::output::agent::{
19	    DEFAULT_SNIPPET_LINES, MAX_SNIPPET_LINES, SearchView, ToDomainError, render_search, search_row_texts,
20	};
21	use crate::pipeline::{SearchRequest, search_with_timeout};
22	use crate::text_search::DEFAULT_MAX_FILES;
23	use crate::types::{Diagnostic, DiagnosticKind};
24	
25	/// AST-aware code search for coding agents.
26	#[derive(Debug, Parser)]
27	#[command(name = "monokl", version, about)]
28	struct Cli {
29	    #[command(subcommand)]
30	    command: Command,
31	}
32	
33	#[derive(Debug, Subcommand)]
34	enum Command {
35	    /// Searches a directory and prints the matching code blocks, best first.
36	    Search(SearchArgs),
37	    /// Prints the file rules of every language as JSON, for the scripts that compare monokl with ripgrep.
38	    #[command(hide = true)]
39	    LanguageRules,
40	}
41	
42	#[derive(Debug, Args)]
43	struct SearchArgs {
44	    /// The query: words, "quoted phrases", `+required`, `-excluded` and `regex:pattern` terms.
45	    query: String,
46	    /// The directory to search.
47	    #[arg(default_value = ".")]
48	    path: Utf8PathBuf,
49	    /// Treats the whole query as one literal term.
50	    #[arg(long)]
51	    exact: bool,
52	    /// Searches test files too.
53	    #[arg(long)]
54	    tests: bool,
55	    /// Searches hidden files and files that .gitignore or .ignore (in the search path or its parents) would exclude.
56	    #[arg(long)]
57	    no_ignore: bool,
58	    /// Searches only this language: typescript, javascript or rust.
59	    #[arg(long, value_enum)]
60	    language: Option<Language>,
61	    /// The most results to print. It also caps the rows `--min-score` keeps, so it can cut below the first eight.
62	    #[arg(long, default_value_t = Budget::default().max_results)]
63	    max_results: usize,
64	    /// Skips this many ranked rows and prints the next page under the same cut and caps. The relevance cut still
65	    /// measures against the top row of the whole result; an offset past the last row prints no rows and exits 0.
66	    #[arg(long, value_name = "N", default_value_t = Budget::default().offset)]
67	    offset: usize,
68	    /// The most estimated tokens (one per three bytes) across the printed rows.
69	    #[arg(long, default_value_t = Budget::default().max_tokens)]
70	    max_tokens: usize,
71	    /// Drops the rows scoring below this fraction of the top row's score, but never one of the first eight. 0 keeps every
72	    /// row up to `--max-results`; 1 keeps only the rows that tie with the top.
73	    #[arg(long, value_name = "FRACTION", default_value_t = Budget::default().min_score, value_parser = parse_min_score)]
74	    min_score: f64,
75	    /// The most matching lines each row's snippet shows, 0 to 3; the rest are counted. 0 prints no snippet, so a
76	    /// variable or type row, which has no signature, shows no declaration text.
77	    #[arg(long, value_name = "N", default_value_t = DEFAULT_SNIPPET_LINES, value_parser = parse_snippet_lines)]
78	    snippet_lines: usize,
79	    /// Stops after this many seconds and prints what was found so far, marked as a partial result. 0 means no limit.
80	    #[arg(long, value_name = "SECONDS", default_value = "30", value_parser = parse_timeout)]
81	    timeout: f64,
82	}
83	
84	/// Reads `--timeout`: a non-negative number of seconds, fractions allowed.
85	fn parse_timeout(text: &str) -> Result<f64, String> {
86	    let seconds: f64 = text.parse().map_err(|e| format!("`{text}` is not a number of seconds: {e}"))?;
87	    Duration::try_from_secs_f64(seconds)
88	        .map(|_| seconds)
89	        .map_err(|e| format!("`{text}` is not a usable number of seconds: {e}"))
90	}
91	
92	/// Reads `--min-score`: a share of the top score, from 0 to 1.
93	fn parse_min_score(text: &str) -> Result<f64, String> {
94	    let fraction: f64 = text.parse().map_err(|e| format!("`{text}` is not a fraction: {e}"))?;
95	    if (0.0..=1.0).contains(&fraction) { Ok(fraction) } else { Err(format!("`{text}` is not between 0 and 1")) }
96	}
97	
98	/// Reads `--snippet-lines`: a count from 0 to [`MAX_SNIPPET_LINES`].
99	fn parse_snippet_lines(text: &str) -> Result<usize, String> {
100	    let lines: usize = text.parse().map_err(|e| format!("`{text}` is not a number of lines: {e}"))?;
101	    if lines <= MAX_SNIPPET_LINES {
102	        Ok(lines)
103	    } else {
104	        Err(format!("`{text}` is more than the {MAX_SNIPPET_LINES} lines a snippet can show"))
105	    }
106	}
107	
108	/// Runs the command line with `args`, writing results to `out` and errors to `err`.
109	///
110	/// Returns success when the command ran, even if it found nothing; failure for any error.
111	#[must_use]
112	pub fn run<I, T>(args: I, out: &mut impl Write, err: &mut impl Write) -> ExitCode
113	where
114	    I: IntoIterator<Item = T>,
115	    T: Into<OsString> + Clone,
116	{
117	    let cli = match Cli::try_parse_from(args) {
118	        Ok(cli) => cli,
119	        Err(e) => {
120	            // clap renders help and version on stdout and usage errors on stderr, with its own exit codes.
121	            let code = e.exit_code();
122	            let target: &mut dyn Write = if e.use_stderr() { err } else { out };
123	            let _written = write!(target, "{e}");
124	            return ExitCode::from(u8::try_from(code).unwrap_or(2));
125	        }
126	    };
127	    match cli.command {
128	        Command::Search(args) => match run_search(&args) {
129	            Ok(text) => exit_code(writeln!(out, "{text}"), ExitCode::SUCCESS),
130	            Err(text) => exit_code(writeln!(err, "{text}"), ExitCode::FAILURE),
131	        },
132	        Command::LanguageRules => exit_code(writeln!(out, "{}", language_rules_json()), ExitCode::SUCCESS),
133	    }
134	}
135	
136	/// `["a","b"]`. Every string in the rules is plain ASCII with nothing to escape.
137	fn json_strings(items: &[&str]) -> String {
138	    let quoted: Vec<String> = items.iter().map(|item| format!("\"{item}\"")).collect();
139	    format!("[{}]", quoted.join(","))
140	}
141	
142	/// The rules in [`crate::analysis::lang`] as one line of JSON, so a script reads them instead of copying them.
143	fn language_rules_json() -> String {
144	    let languages: Vec<String> = Language::ALL
145	        .into_iter()
146	        .filter_map(|language| {
147	            let name = language.to_possible_value()?.get_name().to_owned();
148	            let rules = language.rules();
149	            Some(format!(
150	                "{{\"name\":\"{name}\",\"extensions\":{},\"excluded_suffixes\":{},\"test_stem_suffixes\":{},\"test_stems\":{}}}",
151	                json_strings(rules.extensions),
152	                json_strings(rules.excluded_suffixes),
153	                json_strings(rules.test_stem_suffixes),
154	                json_strings(rules.test_stems),
155	            ))
156	        })
157	        .collect();
158	    format!("{{\"test_dirs\":{},\"languages\":[{}]}}", json_strings(TEST_DIRS), languages.join(","))
159	}
160	
161	/// `ok` unless the write failed. A closed reader (`| head`) is not a failure.
162	fn exit_code(written: std::io::Result<()>, ok: ExitCode) -> ExitCode {
163	    match written {
164	        Err(e) if e.kind() != std::io::ErrorKind::BrokenPipe => ExitCode::FAILURE,
165	        Ok(()) | Err(_) => ok,
166	    }
167	}
168	
169	fn registry() -> AnalyzerRegistry {
170	    let analyzers: Vec<Arc<dyn crate::analysis::LanguageAnalyzer>> = vec![
171	        #[cfg(feature = "lang-ts")]
172	        Arc::new(crate::analysis::ts::TsAnalyzer::new()),
173	        #[cfg(feature = "lang-rust")]
174	        Arc::new(crate::analysis::rust::RustAnalyzer::new()),
175	    ];
176	    AnalyzerRegistry::new(analyzers)
177	}
178	
179	fn run_search(args: &SearchArgs) -> Result<String, String> {
180	    let request = SearchRequest {
181	        root: &args.path,
182	        query: &args.query,
183	        exact: args.exact,
184	        allow_tests: args.tests,
185	        respect_ignore_files: !args.no_ignore,
186	        language: args.language,
187	    };
188	    let result = search_with_timeout(&registry(), &request, timeout(args)).map_err(|e| error_text(&e))?;
189	
190	    let mut ranked = result.ranked;
191	    let mut diagnostics = result.diagnostics;
192	    // Paths print relative to the working directory when they are under it, so every row spends fewer tokens.
193	    if let Some(cwd) = std::env::current_dir().ok().and_then(|dir| Utf8PathBuf::from_path_buf(dir).ok()) {
194	        for block in &mut ranked {
195	            relativize(&mut block.block.file, &cwd);
196	        }
197	        for diagnostic in &mut diagnostics {
198	            if let Some(path) = &mut diagnostic.path {
199	                relativize(path, &cwd);
200	            }
201	        }
202	    }
203	    if result.ceiling_hit {
204	        diagnostics.push(Diagnostic {
205	            kind: DiagnosticKind::Warning,
206	            path: None,
207	            message: format!(
208	                "{} files matched but hits were kept for only the first {DEFAULT_MAX_FILES}; narrow the query or path",
209	                result.files_total
210	            ),
211	        });
212	    }
213	    let budget = Budget {
214	        max_results: args.max_results,
215	        max_tokens: args.max_tokens,
216	        min_score: args.min_score,
217	        offset: args.offset,
218	    };
219	    let view = SearchView { snippet_lines: args.snippet_lines, max_results: args.max_results };
220	    let total_before = ranked.len();
221	    let row_texts = search_row_texts(&ranked, view.snippet_lines);
222	    let response = apply_budget(ranked, total_before, &budget, &row_texts, diagnostics);
223	    Ok(render_search(&response, &view))
224	}
225	
226	/// The deadline `--timeout` asks for; `0` asks for none.
227	fn timeout(args: &SearchArgs) -> Option<Duration> {
228	    (args.timeout > 0.0).then(|| Duration::from_secs_f64(args.timeout))
229	}
230	
231	fn relativize(path: &mut Utf8PathBuf, base: &Utf8PathBuf) {
232	    if let Ok(relative) = path.strip_prefix(base) {
233	        *path = relative.to_owned();
234	    }
235	}
236	
237	fn error_text(error: &MonoklError) -> String {
238	    error.to_domain_error().render()
239	}
