1	//! The agent-layer search budget: cuts a fully ranked, uncapped result down to what one response may carry.
2	//!
3	//! Core returns every ranked block and holds no caps; this module is the first thing a caller does with that result.
4	//! Three rules cut it, in this order, and an offset picks the page they apply to:
5	//!
6	//! 1. The relevance cut drops the rows scoring below [`Budget::min_score`] times the top score, but never one of the
7	//!    first [`MIN_ROWS`]. It is measured against the top row of the whole result, whatever the offset.
8	//! 2. [`Budget::offset`] skips that many of the rows that are left, so a second call returns the next page of the same
9	//!    ranking.
10	//! 3. The row cap, [`Budget::max_results`], applies to the page and wins over the relevance cut's floor.
11	//! 4. The token cap counts the text the caller prints for each row, which the caller supplies, so a cap means what the
12	//!    reader sees and not the size of the code blocks behind the rows.
13	use michi::TruncationOutcome;
14	
15	use crate::types::{Diagnostic, RankedBlock, SearchResponse};
16	
17	/// The rows the relevance cut always keeps, when that many exist.
18	pub const MIN_ROWS: usize = 8;
19	
20	/// What one search response must stay within: a relevance cut, a page offset and two caps.
21	///
22	/// `max_tokens` counts the printed text of the kept rows, as given to [`apply_budget`].
23	///
24	/// # Examples
25	///
26	/// ```
27	/// use monokl::budget::Budget;
28	///
29	/// let budget = Budget::default();
30	/// assert_eq!((budget.max_results, budget.max_tokens, budget.min_score, budget.offset), (20, 20_000, 0.3, 0));
31	/// ```
32	#[derive(Debug, Clone, Copy, PartialEq)]
33	pub struct Budget {
34	    /// The most rows a response may carry. It wins over the floor of [`MIN_ROWS`].
35	    pub max_results: usize,
36	    /// The most estimated tokens (see [`count_tokens`]) the kept rows' printed text may total.
37	    pub max_tokens: usize,
38	    /// The share of the top score a row needs to be kept, from `0.0` (no relevance cut) to `1.0` (only rows that tie
39	    /// with the top row). The first [`MIN_ROWS`] rows are kept whatever their score.
40	    pub min_score: f64,
41	    /// The rows to skip, counted after the relevance cut and before the caps, so the caps bound the page and not the
42	    /// skipped rows. An offset at or past the last kept row returns no rows.
43	    pub offset: usize,
44	}
45	
46	impl Default for Budget {
47	    fn default() -> Self {
48	        Self { max_results: 20, max_tokens: 20_000, min_score: 0.3, offset: 0 }
49	    }
50	}
51	
52	/// Returns the estimated token count of `text`: its byte length divided by three, rounded up.
53	///
54	/// Code and TOON rows run 3.0 to 3.6 bytes per `o200k_base` token, so this reads about a tenth high and rarely low. A
55	/// tokenizer would be exact for one vocabulary only, and no vocabulary is the one every reader uses. Building a real one
56	/// costs about 55 ms on the first row, more than the rest of a search.
57	///
58	/// # Examples
59	///
60	/// ```
61	/// use monokl::budget::count_tokens;
62	///
63	/// assert_eq!(count_tokens(""), 0);
64	/// assert_eq!(count_tokens("hello world"), 4);
65	/// ```
66	pub fn count_tokens(text: &str) -> usize {
67	    text.len().div_ceil(3)
68	}
69	
70	/// How many leading rows of `ranked` the relevance cut keeps: those scoring at least `min_score` times the top row's
71	/// score, and never fewer than [`MIN_ROWS`] (or all rows, when there are fewer). `ranked` is in rank order, so the
72	/// scores fall and the kept rows are a prefix. A top score of 0 makes every row relevant.
73	fn relevant_rows(ranked: &[RankedBlock], min_score: f64) -> usize {
74	    let Some(top) = ranked.first() else { return 0 };
75	    let floor = min_score * top.final_score;
76	    let above = ranked.iter().take_while(|row| row.final_score >= floor).count();
77	    above.max(MIN_ROWS.min(ranked.len()))
78	}
79	
80	/// Keeps the page of `ranked` that starts at [`Budget::offset`] among the rows passing the relevance cut and whose
81	/// printed rows fit `budget`, and reports what was cut.
82	///
83	/// `row_texts` holds the text that is printed for each block, in the same order; the token cap counts that text, not
84	/// the block's code. Blocks are never split or reordered. The relevance cut keeps the rows scoring at least
85	/// [`Budget::min_score`] times the top score, and at least [`MIN_ROWS`] rows; the row cap then applies to what it kept,
86	/// so a `max_results` below [`MIN_ROWS`] wins. The token cut falls at the first block that would break the cap, so a row
87	/// larger than the whole token budget leaves no results. The offset skips rows of the relevant prefix before either cap
88	/// counts, so the caps bound the page, and the relevance cut does not move with it. `total_before` is the count the caller had before any cut,
89	/// which may exceed `ranked.len()` when an earlier stage already dropped candidates; the response is truncated whenever
90	/// fewer blocks are kept than that, which includes every page after the first. `diagnostics` pass through untouched.
91	///
92	/// # Examples
93	///
94	/// ```
95	/// use monokl::budget::{apply_budget, Budget};
96	///
97	/// let response = apply_budget(Vec::new(), 0, &Budget::default(), &[], Vec::new());
98	/// assert!(!response.truncated);
99	/// assert_eq!(response.total_blocks_before_truncation, 0);
100	/// assert_eq!(response.blocks_cut_by_relevance, 0);
101	/// ```
102	pub fn apply_budget(
103	    ranked: Vec<RankedBlock>,
104	    total_before: usize,
105	    budget: &Budget,
106	    row_texts: &[String],
107	    diagnostics: Vec<Diagnostic>,
108	) -> SearchResponse {
109	    let mut kept = Vec::new();
110	    let mut total_tokens = 0usize;
111	    debug_assert_eq!(ranked.len(), row_texts.len(), "each block needs its printed row");
112	    let relevant = relevant_rows(&ranked, budget.min_score);
113	    let blocks_cut_by_relevance = ranked.len() - relevant;
114	    for (block, text) in ranked.into_iter().zip(row_texts).take(relevant).skip(budget.offset) {
115	        if kept.len() >= budget.max_results {
116	            break;
117	        }
