141	#[derive(Debug, Clone)]
142	#[cfg_attr(feature = "serde", derive(serde::Serialize))]
143	#[cfg_attr(feature = "serde", serde(into = "DomainErrorWire"))]
144	#[non_exhaustive]
145	pub struct DomainError {
146	    /// The error classification.
147	    pub code: ErrorCode,
148	    /// Human-readable message.
149	    pub message: String,
150	    /// Why it happened, outermost first: one entry per underlying cause, rendered as `causes[N]: …` after the
151	    /// message. Diagnosis only; what the agent should do next goes in `hints`.
152	    pub causes: Vec<String>,
153	    /// Contextual hints, rendered as a trailing `help[N]:` block.
154	    pub hints: Vec<Hint>,
155	    /// Optional structured recovery hint.
156	    pub recovery: Option<RecoveryHint>,
157	    /// Whether calling again is expected to help without repeating an effect. Defaults to `true` only for
158	    /// `RateLimited` and `Unavailable` (the request was not processed); set it for a `Timeout` or `ExternalFailure`
159	    /// only when the operation is idempotent, since the failed attempt may have taken effect.
160	    pub retryable: bool,
161	    /// Parsed `Retry-After` delay, if known.
162	    pub retry_after: Option<Duration>,
163	}
164	
165	impl DomainError {
166	    /// Create a domain error. The message is tool-author text, never data: michi renders it as the error's own
167	    /// voice, and a value copied from a file, web page or user field can carry instructions. See the trust model in
168	    /// `docs/spec/02-toon-format.md`.
169	    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
170	        let mut err = Self {
171	            retryable: code.is_retryable_by_default(),
172	            code,
173	            message: message.into(),
174	            causes: Vec::new(),
175	            hints: Vec::new(),
176	            recovery: None,
177	            retry_after: None,
178	        };
179	        err.sync_effect_hint();
180	        err
181	    }
182	
183	    /// Keeps [`MAY_HAVE_TAKEN_EFFECT_HINT`] present exactly while the error's code may have taken effect and it is not
184	    /// marked retryable.
185	    fn sync_effect_hint(&mut self) {
186	        let wanted = self.code.may_have_taken_effect() && !self.retryable;
187	        let present = self.hints.iter().any(|h| h.as_str() == MAY_HAVE_TAKEN_EFFECT_HINT);
188	        if wanted && !present {
189	            self.hints.push(Hint::new(MAY_HAVE_TAKEN_EFFECT_HINT));
190	        } else if !wanted && present {
191	            self.hints.retain(|h| h.as_str() != MAY_HAVE_TAKEN_EFFECT_HINT);
192	        }
193	    }
194	
195	    /// Build a domain error from an existing error, keeping only its own `Display` as `message`.
196	    ///
197	    /// The `source()` chain is **not** copied: underlying errors often carry URLs with tokens, file paths and other
198	    /// internals that should not reach an agent. Use [`DomainError::from_error_with_causes`] to opt in to the chain.
199	    /// The top-level `Display` is still agent-visible, so make sure it is safe to show; if it is not, build the
200	    /// error with [`DomainError::new`] and a message you wrote. The message is tool-author text, never data. As a
201	    /// safety net, `user:password@` in any URL is replaced with `[REDACTED]` ([`crate::redact::redact_url_userinfo`]);
202	    /// that is best-effort and covers nothing else.
203	    ///
204	    /// ```
205	    /// use michi_core::{DomainError, ErrorCode};
206	    ///
207	    /// #[derive(Debug, thiserror::Error)]
208	    /// #[error("sync failed")]
209	    /// struct Sync(#[source] std::io::Error);
210	    ///
211	    /// let io = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "/home/ci/.netrc: permission denied");
212	    /// let e = DomainError::from_error(ErrorCode::ExternalFailure, &Sync(io));
213	    /// assert_eq!(e.message, "sync failed");
214	    /// assert!(e.causes.is_empty());
215	    /// ```
216	    pub fn from_error(code: ErrorCode, err: &(dyn std::error::Error + 'static)) -> Self {
217	        Self::new(code, crate::redact::redact_url_userinfo(&err.to_string()))
218	    }
219	
220	    /// Like [`DomainError::from_error`], and also copies the `source()` chain into `causes`. Opt-in: every link's
221	    /// `Display` becomes agent-visible text, so use it only when the whole chain is safe to show (no URLs with
222	    /// tokens, no paths or internals you would not print to an end user). URL userinfo is redacted in every link, as in
223	    /// [`DomainError::from_error`].
224	    ///
225	    /// Each `source()` link, outermost first, adds its `Display` as one entry of `causes` (never a hint: causes are
226	    /// diagnosis, hints are guidance). A link whose text is already contained in the last text kept (the message, or
227	    /// the previous cause kept) is skipped, because `thiserror` messages often embed their source
228	    /// (`#[error("walk failed: {0}")]`) and would otherwise repeat it. Line breaks stay inside their entry; the
229	    /// renderers escape them. The walk stops after 128 links, so a cyclic `source()` cannot loop.
230	    ///
231	    /// The chain is kept as text only: no source error is stored, so [`std::error::Error::source`] on the result is
232	    /// still `None`, and the result stays `Clone`, `Send` and `Sync`. Prefix the message yourself if you want one
233	    /// (`e.message = format!("walk: {}", e.message)`).
234	    ///
235	    /// ```
236	    /// use michi_core::{DomainError, ErrorCode};
237	    ///
238	    /// #[derive(Debug, thiserror::Error)]
239	    /// #[error("walk failed: {0}")]
