#!/usr/bin/env python3
"""Runs monokl on 20 harness questions, re-renders each response's rows in other formats and counts tokens."""
import json
import re
import subprocess
import sys
from pathlib import Path

import tiktoken

BIN = sys.argv[1]
CLONES = Path("/Users/gabe/Projects/monokl/.claude/worktrees/agent-af286df18d56a59f5/target/rg-compare")
QUESTIONS = Path("/Users/gabe/Projects/monokl/.claude/worktrees/agent-aa23b683c47108dc7/scripts/rg-compare.questions")
OUT = Path(sys.argv[2])
enc = tiktoken.get_encoding("o200k_base")
enc2 = tiktoken.get_encoding("cl100k_base")


def split_cells(line):
    cells, cur, i, quoted = [], [], 0, False
    while i < len(line):
        c = line[i]
        if quoted:
            if c == "\\":
                n = line[i + 1]
                cur.append({"n": "\n", "r": "\r", "t": "\t"}.get(n, n))
                i += 2
                continue
            if c == '"':
                quoted = False
            else:
                cur.append(c)
        elif c == '"':
            quoted = True
            cell_quoted = True
        elif c == ",":
            cells.append("".join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    cells.append("".join(cur))
    return cells


def parse(out):
    lines = out.split("\n")
    head = re.match(r"search\[(\d+)\]\{(.*)\}:$", lines[0])
    if not head:
        return None, [], lines[1:]
    fields = head.group(2).split(",")
    rows, tail = [], []
    for l in lines[1:]:
        if l.startswith("  ") and len(rows) < int(head.group(1)):
            rows.append(split_cells(l[2:]))
        else:
            tail.append(l)
    return fields, rows, tail


def md_cell(v):
    if v == "null":
        return ""
    return v.replace("|", "\\|").replace("\n", "<br>")


def md_table(fields, rows):
    out = ["| " + " | ".join(fields) + " |", "|" + "|".join("---" for _ in fields) + "|"]
    for r in rows:
        out.append("| " + " | ".join(md_cell(c) for c in r) + " |")
    return "\n".join(out)


def tsv(fields, rows):
    out = ["\t".join(fields)]
    for r in rows:
        out.append("\t".join("" if c == "null" else c.replace("\n", "\\n").replace("\t", " ") for c in r))
    return "\n".join(out)


def grep_style(fields, rows):
    """path:start-end kind parent signature, snippet lines indented. Rank is the order, score is dropped."""
    ix = {f: i for i, f in enumerate(fields)}
    out = []
    for r in rows:
        g = lambda f: "" if r[ix[f]] == "null" else r[ix[f]]
        head = f"{g('file')}:{g('lineStart')}-{g('lineEnd')} {g('nodeKind')}"
        if g("parent"):
            head += f" [{g('parent')}]"
        if g("symbolSignature"):
            head += " " + g("symbolSignature").replace("\n", " ")
        out.append(head)
        if g("snippet"):
            for s in g("snippet").split("\n"):
                out.append("  " + s)
    return "\n".join(out)


def json_rows(fields, rows, indent):
    objs = []
    for r in rows:
        o = {}
        for f, c in zip(fields, r):
            if c == "null":
                o[f] = None
            elif f in ("lineStart", "lineEnd", "rank"):
                o[f] = int(c)
            elif f == "finalScore":
                o[f] = float(c)
            else:
                o[f] = c
        objs.append(o)
    return json.dumps(objs, indent=indent, separators=(",", ":") if indent is None else None, ensure_ascii=False)


def csv_std(fields, rows):
    def q(c):
        c = "" if c == "null" else c
        return '"' + c.replace('"', '""') + '"' if any(ch in c for ch in ',"\n') else c
    return "\n".join([",".join(fields)] + [",".join(q(c) for c in r) for r in rows])


def toks(s):
    return len(enc.encode(s)), len(enc2.encode(s))


# Pick 20 questions evenly across the cloned repos' rows.
rows_q = []
for line in QUESTIONS.read_text().splitlines():
    if line.startswith("#") or "|" not in line:
        continue
    p = [x.strip() for x in line.split("|")]
    if len(p) >= 4 and (CLONES / p[0]).is_dir():
        rows_q.append((p[0], p[1]))
step = len(rows_q) / 20
picked = [rows_q[int(i * step)] for i in range(20)]

fmts = ["toon_current", "markdown", "tsv", "csv", "grep_style", "json_compact", "json_pretty"]
tot = {f: [0, 0, 0] for f in fmts}
per = []
for repo, q in picked:
    r = subprocess.run([BIN, "search", q, "."], cwd=CLONES / repo, capture_output=True, text=True)
    out = r.stdout.rstrip("\n")
    fields, rows, tail = parse(out)
    if fields is None:
        per.append((repo, q, "no rows", out[:80]))
        continue
    tail_txt = "\n".join(tail)
    texts = {
        "toon_current": "\n".join(out.split("\n")[: 1 + len(rows)]),
        "markdown": md_table(fields, rows),
        "tsv": tsv(fields, rows),
        "csv": csv_std(fields, rows),
        "grep_style": grep_style(fields, rows),
        "json_compact": json_rows(fields, rows, None),
        "json_pretty": json_rows(fields, rows, 2),
    }
    rec = {"repo": repo, "q": q, "rows": len(rows), "tail_bytes": len(tail_txt.encode())}
    for f, t in texts.items():
        b = len(t.encode())
        o, c = toks(t)
        rec[f] = (b, o, c)
        tot[f][0] += b
        tot[f][1] += o
        tot[f][2] += c
    per.append(rec)

print(f"queries run: {sum(1 for p in per if isinstance(p, dict))} of 20; rows total: {sum(p['rows'] for p in per if isinstance(p, dict))}")
print("tail (totalCount/help) bytes total:", sum(p["tail_bytes"] for p in per if isinstance(p, dict)))
print(f"{'format':14} {'bytes':>8} {'o200k':>8} {'cl100k':>8}  vs toon(o200k)")
base = tot["toon_current"][1]
for f in fmts:
    b, o, c = tot[f]
    print(f"{f:14} {b:8d} {o:8d} {c:8d}  {100 * (o - base) / base:+.1f}%")
print("per query (o200k tokens): query | rows | toon | markdown | grep_style")
for p in per:
    if isinstance(p, dict):
        print(f"{p['repo']:9} {p['q'][:34]:34} {p['rows']:3d} {p['toon_current'][1]:6d} {p['markdown'][1]:6d} {p['grep_style'][1]:6d}")
    else:
        print(p)
OUT.write_text(json.dumps([p for p in per if isinstance(p, dict)], indent=1))

