use michi::{AgentResponse, BudgetSummary, OutputFormat, ProvenanceBlock, Section, SectionCost};
use michi::toon::Value;

fn main() {
    let rows = vec![vec![Value::from("src/a.ts"), Value::from(1usize)]];
    let section = Section::toon("search", vec!["file".into(), "line".into()], rows).total_count(Some(96)).truncated(true);
    let budget = BudgetSummary::new().max_tokens(20000).max_items(20).tokens_used(1850).truncated(true);
    let prov = ProvenanceBlock::new()
        .entry("query", "create store state")
        .entry("language", "any")
        .entry("tests", "false")
        .entry("ignoreFiles", "respected")
        .entry("minScore", "0.3");
    let r = AgentResponse::new("search")
        .section(section.clone())
        .hint("showing 20 of 96; next: --offset 20")
        .budget(budget.clone());
    println!("--- budget only\n{}", r.render(OutputFormat::Text));
    let r = AgentResponse::new("search").section(section.clone()).budget(budget.clone()).provenance(prov.clone());
    println!("--- budget+provenance\n{}", r.render(OutputFormat::Text));
    let r2 = AgentResponse::new("search")
        .section(section)
        .section(Section::toon("diagnostics", vec!["kind".into(), "path".into(), "message".into()], vec![vec![Value::from("skipped"), Value::from("a.ts"), Value::from("over 4 MiB")]]))
        .budget(budget.section(SectionCost::new("search", 20).total(96).truncated(true)))
        .provenance(prov);
    println!("--- two sections\n{}", r2.render(OutputFormat::Text));
    let bad = AgentResponse::new("search").section(Section::text("search", "x")).section(Section::text("search", "y"));
    println!("--- dup\n{}", bad.render(OutputFormat::Text));
}

